example.programlisting:
[pages.triggers]
title='Show the triggers only'
line1={type='ratio', scalers=['example.triggers.live', 'example.triggers']}            
line2={type='single', scalers=['example.sin1']}
line4={type='pair', scalers=['example.sin2', 'example.sin3']}

[datasource.raw2] url='tcp://spdaq11.frib.msu.edu' version= 11 # NSCLDAQ Version ' scalers=['name1', 'name2', 'name3']
[datasource.raw1] url='tcp://spdaq10.frib.msu.edu/raw_1' version=12.0 # NSCLDAQ Version. scalers=['name1', 'name2', 'name3'] incremental=false
[pages.apage] title='This is the page title' line1= {type='single', scalers=['raw2.name1']} line2= {type = 'pair', scalers=['raw1.name1', 'raw1.name2']} line3= {type = 'ratio', scalers=['raw2.name2', 'raw2.name3']}
[pages.another] title='this is a second page' line1= {type = 'ratio', scalers=['raw2.name3', 'raw2.name2']} line3= {type = 'ratio', scalers=['raw1.name1', 'raw1.name3']}
[graph] individual=['raw1.name1', 'raw2.name2'] ratios = [['raw1.name2', 'raw1.name3'], ['raw2.name1', 'raw2.name2']]
[alarms] raw1.name1={high=1234, low=10}
[alarmcolors] lowalarm='green' highalarm='red' bothalarms='blue' noalarm='black'
